B.bIP=new A.dY([1,4],t.Ih)
B.z7=new A.mK(0,"uebelkeit")
B.bmA=s(["100 g Reis","700 ml Gem\xfcsebr\xfche","1 Karotte","1 St\xfcck frischer Ingwer (etwa daumennagelgro\xdf)","1 TL \xd6l","etwas Salz","Petersilie"],t.s)
B.biT=s(["Karotte sch\xe4len und klein w\xfcrfeln, Ingwer fein reiben.","\xd6l erhitzen und Karotte mit Ingwer kurz anschwitzen.","Br\xfche und Reis zugeben, etwa 15 Minuten leise k\xf6cheln, bis der Reis weich ist.","Mit Salz abschmecken und mit Petersilie bestreuen."],t.s)
B.bE_=new A.hr("Milde Ingwer-Reissuppe",B.bIP,B.z7,25,2,"Warm, mild und leicht verdaulich. Viele finden eine klare Suppe mit Reis bei \xdcbelkeit angenehm.",B.bmA,B.biT,"Iss lieber kleine Portionen \xfcber den Tag verteilt. Eine trockene Scheibe Zwieback vor dem Aufstehen hilft manchen morgens.",!0)
B.dB=new A.dY([1,2,3,4],t.Ih)
B.bm0=s(["50 g zarte Haferflocken","250 ml Milch oder Pflanzendrink mit Kalzium","1 Banane","1 TL Honig oder Ahornsirup (nach Wunsch)","Zimt"],t.s)
B.bow=s(["Haferflocken mit der Milch unter R\xfchren kurz aufkochen und 3 bis 4 Minuten quellen lassen.","Banane in Scheiben schneiden, die H\xe4lfte unterr\xfchren.","Mit der restlichen Banane, Zimt und nach Wunsch etwas S\xfc\xdfe servieren."],t.s)
B.bDR=new A.hr("Haferbrei mit Banane",B.dB,B.z7,10,1,"Ein sanftes Fr\xfchst\xfcck, das lange s\xe4ttigt und den Magen kaum reizt.",B.bm0,B.bow,"Vollkorn liefert Ballaststoffe und Eisen. Milch oder ein angereicherter Pflanzendrink bringt Kalzium mit.",!0)
B.hp=new A.dY([1,2,3],t.Ih)
B.bkj=s(["400 g Kartoffeln (mehligkochend)","2 Karotten","100 ml warme Milch","1 EL Butter oder \xd6l","Salz, etwas Muskat"],t.s)
B.bjh=s(["Kartoffeln und Karotten sch\xe4len, w\xfcrfeln und in Salzwasser etwa 20 Minuten weich kochen.","Abgie\xdfen und zerstampfen.","Warme Milch und Butter unterr\xfchren, mit Salz und Muskat abschmecken."],t.s)
B.bE5=new A.hr("Kartoffel-Karotten-P\xfcree",B.hp,B.z7,30,2,"Weich, warm und ohne starken Geruch. Gut, wenn vieles zu intensiv schmeckt.",B.bkj,B.bjh,"Dazu passt ein hartgekochtes Ei oder ein Klecks pasteurisierter Quark f\xfcr mehr Eiwei\xdf.",!0)
B.mk=new A.mK(1,"eisen")
B.b60=s(["200 g rote Linsen","1 Zwiebel","2 Karotten","1 Paprika","1 EL Tomatenmark","800 ml Gem\xfcsebr\xfche","1 EL \xd6l","Saft einer halben Zitrone","Kreuzk\xfcmmel, Salz"],t.s)
B.b41=s(["Zwiebel w\xfcrfeln, Karotten und Paprika klein schneiden und im \xd6l anbraten.","Tomatenmark und Kreuzk\xfcmmel kurz mitr\xf6sten.","Linsen und Br\xfche zugeben und 15 bis 20 Minuten k\xf6cheln, bis alles weich ist.","Mit Zitronensaft und Salz abschmecken."],t.s)
B.bE6=new A.hr("Linsen-Gem\xfcse-Eintopf",B.hp,B.mk,35,3,"H\xfclsenfr\xfcchte liefern pflanzliches Eisen, Eiwei\xdf und Folat. Vitamin C aus dem Gem\xfcse hilft dem K\xf6rper, das Eisen aufzunehmen.",B.b60,B.b41,"Zitronensaft oder Paprika erh\xf6hen die Eisenaufnahme. Kaffee und Schwarztee zum Essen bremsen sie.",!0)
B.oU=new A.dY([2,3,4],t.Ih)
B.bi3=s(["200 g rote Linsen","1 Zwiebel","2 Knoblauchzehen","1 St\xfcck Ingwer","400 ml Kokosmilch","200 ml Wasser","200 g junger Spinat (frisch gewaschen oder TK)","1 TL Kurkuma, 1 TL Kreuzk\xfcmmel","Saft einer halben Zitrone","Salz"],t.s)
B.bjG=s(["Zwiebel, Knoblauch und Ingwer fein hacken und in etwas \xd6l anschwitzen.","Gew\xfcrze kurz mitr\xf6sten, dann Linsen, Kokosmilch und Wasser zugeben.","Etwa 15 Minuten k\xf6cheln, bis die Linsen zerfallen.","Spinat unterr\xfchren und zusammenfallen lassen, mit Zitrone und Salz abschmecken.","Mit Reis oder Fladenbrot servieren."],t.s)
B.bDQ=new A.hr("Rotes Linsen-Dal mit Spinat",B.oU,B.mk,30,3,"Ein w\xfcrziges, cremiges Gericht mit Eisen, Eiwei\xdf und Folat. Es ist milder gew\xfcrzt als in der K\xfcche \xfcblich.",B.bi3,B.bjG,"Reste rasch abk\xfchlen, im K\xfchlschrank lagern und nur einmal ganz durcherhitzen.",!0)
B.oV=new A.dY([2,3],t.Ih)
B.z8=new A.mK(2,"kalzium")
B.bqN=s(["500 g Kartoffeln","300 g Brokkoli","150 g geriebener K\xe4se (pasteurisiert, z. B. Gouda)","200 ml Milch","2 Eier","Salz, Pfeffer, Muskat"],t.s)
B.aTB=s(["Kartoffeln in Scheiben schneiden und 10 Minuten vorkochen, Brokkoli in R\xf6schen etwa 3 Minuten blanchieren.","Beides in eine Form schichten.","Milch mit Eiern, Salz, Pfeffer und Muskat verquirlen, dar\xfcbergie\xdfen und mit K\xe4se bestreuen.","Bei 180 Grad etwa 25 Minuten backen, bis alles fest und durchgegart ist."],t.s)
B.bDS=new A.hr("Brokkoli-Kartoffel-Auflauf",B.oV,B.z8,50,3,"Brokkoli und K\xe4se liefern Kalzium. Der Auflauf wird durchgebacken, damit er auch f\xfcr die Schwangerschaft passt.",B.bqN,B.aTB,"Die Eier m\xfcssen ganz gestockt sein. So ist der Auflauf sicher.",!0)
B.boo=s(["200 g Magerquark oder Joghurt (pasteurisiert)","100 g Beeren (frisch gewaschen oder TK aufgetaut)","1 EL geschrotete Leinsamen","1 TL Honig (nach Wunsch)"],t.s)
B.bnJ=s(["Quark glatt r\xfchren.","Beeren und Leinsamen darauf geben.","Nach Wunsch mit Honig s\xfc\xdfen."],t.s)
B.bE7=new A.hr("Quark mit Beeren und Leinsamen",B.dB,B.z8,5,1,"Schnell gemacht, mit Eiwei\xdf, Kalzium und Ballaststoffen. Ein guter Snack f\xfcr zwischendurch.",B.boo,B.bnJ,"Tiefgek\xfchlte Beeren vor dem Verzehr kurz erhitzen, denn sie k\xf6nnen Krankheitserreger tragen (BfR). Frische Beeren gr\xfcndlich waschen.",!0)
B.bn6=s(["250 g H\xe4hnchenbrust","1 rote Paprika","1 Zucchini","1 Zwiebel","2 EL \xd6l","1 TL Paprikapulver","200 g Reis oder Nudeln zum Servieren","Salz, Pfeffer"],t.s)
B.bqc=s(["Fleisch in Streifen schneiden, Gem\xfcse w\xfcrfeln.","Fleisch im hei\xdfen \xd6l rundum anbraten, bis es innen keine rosa Stellen mehr hat.","Gem\xfcse zugeben und 5 bis 8 Minuten mitbraten, w\xfcrzen.","Mit Reis oder Nudeln servieren."],t.s)
B.bE4=new A.hr("H\xe4hnchen-Gem\xfcse-Pfanne",B.oU,B.mk,25,2,"Mageres Fleisch und buntes Gem\xfcse in einer Pfanne, mit Eiwei\xdf, Eisen und Vitamin C.",B.bn6,B.bqc,"Schneidebrett und Messer nach dem rohen Fleisch hei\xdf absp\xfclen, bevor du Gem\xfcse schneidest.",!1)
B.EU=new A.mK(4,"energie")
B.bjK=s(["2 Scheiben Vollkornbrot","1 reife Avocado","1 hartgekochtes Ei (mindestens 10 Minuten gekocht)","Zitronensaft, Salz, Pfeffer","Kresse oder Tomate"],t.s)
B.bn5=s(["Ei 10 Minuten kochen, abschrecken und pellen.","Avocado zerdr\xfccken und mit Zitronensaft, Salz und Pfeffer w\xfcrzen.","Auf das Brot streichen, Ei in Scheiben darauflegen und mit Kresse oder Tomate belegen."],t.s)
B.bDX=new A.hr("Vollkornbrot mit Avocado und Ei",B.dB,B.EU,15,1,"Ein s\xe4ttigendes Fr\xfchst\xfcck oder Abendessen mit gesunden Fetten, Eiwei\xdf und Ballaststoffen.",B.bjK,B.bn5,"Rohe Sprossen sind in der Schwangerschaft nicht empfohlen (BfR). Nimm Kresse aus dem Topf, gr\xfcndlich gewaschen, oder lass sie weg.",!0)
B.bjS=s(["80 g Hirse","400 ml Milch oder Pflanzendrink","1 Apfel","1 EL gehackte Mandeln","Zimt"],t.s)
B.bbw=s(["Hirse in einem Sieb hei\xdf absp\xfclen.","Mit der Milch aufkochen und 10 bis 12 Minuten quellen lassen.","Apfel reiben oder klein schneiden und mit Zimt unterr\xfchren.","Mit Mandeln bestreuen."],t.s)
B.bDW=new A.hr("Hirsebrei mit Apfel",B.oU,B.mk,20,2,"Hirse enth\xe4lt Eisen und Magnesium und ist glutenfrei. Der Brei w\xe4rmt und macht lange satt.",B.bjS,B.bbw,null,!0)
B.bIU=new A.dY([3,4],t.Ih)
B.a7m=new A.mK(5,"sodbrennen")
B.bj4=s(["500 g Hokkaido-K\xfcrbis","1 Kartoffel","1 Zwiebel","600 ml Gem\xfcsebr\xfche","1 EL \xd6l","50 ml Sahne oder Kokosmilch","Salz, etwas Muskat"],t.s)
B.bmq=s(["K\xfcrbis (Schale kann bleiben), Kartoffel und Zwiebel w\xfcrfeln.","Alles im \xd6l kurz anschwitzen und mit Br\xfche aufgie\xdfen.","15 bis 20 Minuten weich kochen und p\xfcrieren.","Sahne unterr\xfchren und abschmecken."],t.s)
B.bDY=new A.hr("Milde K\xfcrbissuppe",B.bIU,B.a7m,30,3,"Mild, ohne viel S\xe4ure und Sch\xe4rfe. Das kann bei Sodbrennen im letzten Drittel helfen.",B.bj4,B.bmq,"Iss lieber mehrere kleine Mahlzeiten und bleib danach eine halbe Stunde aufrecht. Bei starkem Sodbrennen sprich mit deiner \xc4rztin.",!0)
B.biS=s(["200 g gekochter Reis (vom Vortag, gut gek\xfchlt)","2 Eier","200 g Gem\xfcse (Karotte, Erbsen, Mais, Lauch)","2 EL \xd6l","Sojasauce, Pfeffer"],t.s)
B.bmK=s(["Gem\xfcse klein schneiden und im \xd6l 5 Minuten anbraten.","Reis zugeben und mitbraten, bis er hei\xdf ist.","Reis zur Seite schieben, Eier in die Pfanne geben und fest stocken lassen, dann untermischen.","Mit Sojasauce und Pfeffer abschmecken."],t.s)
B.bE1=new A.hr("Gem\xfcse-Reispfanne mit Ei",B.oV,B.EU,25,2,"Ein schnelles Gericht aus Resten. Das Ei wird ganz durchgegart.",B.biS,B.bmK,"Reis schnell abk\xfchlen lassen und nicht l\xe4nger als einen Tag im K\xfchlschrank aufbewahren.",!0)
B.a7n=new A.mK(6,"jod")
B.blD=s(["2 Lachsfilets (durchgegart)","400 g Kartoffeln","250 g Brokkoli","1 EL \xd6l","Zitrone, Salz, Pfeffer, Dill"],t.s)
B.bjg=s(["Kartoffeln sch\xe4len, halbieren und 20 Minuten kochen.","Brokkoli in den letzten 5 Minuten mitgaren.","Lachs w\xfcrzen und in der Pfanne oder im Ofen (180 Grad) 12 bis 15 Minuten garen, bis er innen nicht mehr glasig ist.","Mit Zitrone und Dill servieren."],t.s)
